#!/data/data/com.termux/files/usr/bin/bash

RED='\033[1;31m'
GREEN='\033[1;32m'
YELLOW='\033[1;33m'
CYAN='\033[1;36m'
WHITE='\033[1;37m'
PINK='\033[1;95m'
NC='\033[0m'

logo(){
clear
echo -e "${PINK}"
echo "                    /\_/\                    "
echo "                   / o o \                   "
echo "                  (   \"   )                  "
echo "                   \~(*)~/                   "
echo "                    - ^ -                    "
echo ""
echo "             Brutall WhatsApp Tool"
echo "                 Version 4.0"
echo -e "${NC}"
}

fake_verify(){
echo -e "${CYAN}Memverifikasi data engine...${NC}"
size=${#ENGINE_DATA}
step=$((size/100))
count=0
for i in $(seq 1 100); do
    count=$((count+step))
    printf "\r${WHITE}Verifikasi Engine : ${GREEN}%d%%${NC}" "$i"
    sleep 0.02
done
echo ""
}

engine(){
target=$1
n=1
while true
do
if ((n % 2)); then
echo -e "${RED}[ENGINE-$n] mencoba spamm ke nomor $target ...${NC}"
else
echo -e "${GREEN}[ENGINE-$n] mencoba spamm ke nomor $target ...${NC}"
fi
sleep 0.01
n=$((n+1))
done
}

logo
echo -ne "${YELLOW}Masukkan Nomor Target : ${WHITE}"
read nomor

echo ""
echo -e "${CYAN}Menghubungkan ke server Brutall...${NC}"
sleep 1

fake_verify

echo ""
echo -e "${GREEN}Engine Aktif...${NC}"
sleep 1

engine "$nomor"

# DATA ENGINE BESAR
ENGINE_DATA="
"
